head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07330";
scwin.dts_List = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.ldMktTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07330.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb69", attr: "label", fn: function () { return String(dma_comInfo.get("lgshrhdEngNm")); } },
        { childId: "__rb72", attr: "label", fn: function () { return String(dma_comInfo.get("instInvstNm")); } },
        { childId: "__rb73", attr: "label", fn: function () { return String(dma_comInfo.get("instInvstCmstkShrs")) + " 주"; } },
        { childId: "__rb74", attr: "label", fn: function () { return String(dma_comInfo.get("instInvstPrefstkShrs")) + " 주"; } },
        { childId: "__rb75", attr: "label", fn: function () { return String(dma_comInfo.get("instInvstShrRt")) + " %"; } },
        { childId: "__rb76", attr: "label", fn: function () { return String(dma_comInfo.get("instInvstCnt")) + " 사"; } },
        { childId: "__rb77", attr: "label", fn: function () { return String(dma_comInfo.get("empstkassoGrntprnCnt")) + " 인"; } },
        { childId: "__rb78", attr: "label", fn: function () { return String(dma_comInfo.get("empstkassoGrntShrs")) + " 주"; } },
        { childId: "__rb79", attr: "label", fn: function () { return String(dma_comInfo.get("empstkassoRto")) + " %"; } },
        { childId: "__rb80", attr: "label", fn: function () { return String(dma_comInfo.get("stkoptGrntprnCnt")) + " 인"; } },
        { childId: "__rb81", attr: "label", fn: function () { return String(dma_comInfo.get("stkoptGrntShrs")) + " 주"; } },
        { childId: "__rb82", attr: "label", fn: function () { return String(dma_comInfo.get("stkoptRto")) + " %"; } },
        { childId: "__rb83", attr: "label", fn: function () { return String(dma_comInfo.get("prsntPrefstkShrs")) + " 주"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_listTpClssCd", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_2", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_3", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_4", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_5", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_6", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_7", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_8", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_9", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_lgshrhdNm", fn: function(){ return ((dma_comInfo.get("lgshrhdNm") ?? (() => { throw new Error("unresolved:" + "comInfo.lgshrhdNm"); })()) !==''); } }, { id: "if_ovr1pctOwnrNm", fn: function(){ return ((dma_comInfo.get("ovr1pctOwnrNm") ?? (() => { throw new Error("unresolved:" + "comInfo.ovr1pctOwnrNm"); })()) !==''); } }, { id: "if_listTpClssCd_10", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") ==='2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

