        { childId: "__rb13", fn: function () { return String(dma_comInfo.get("lgshrhdRelprnShrRt")) + " %"; } },
        { childId: "__rb17", fn: function () { return String(dma_comInfo.get("lssrpAfpubofrShrRt")) + " %"; } },
