        { childId: "__rb19", fn: function () { return String((String(dma_comInfo.get("lgshrhdPrefstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))); } },
        { childId: "__rb20", fn: function () { return String(((String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdPrefstkShrs"))) + (String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs"))))); } },
        { childId: "__rb21", fn: function () { return String((String(dma_comInfo.get("lgshrhdShrRt")) + String(dma_comInfo.get("lgshrhdRelprnShrRt")))) + " %"; } },
