        { childId: "__rb24", fn: function () { return String((String(dma_comInfo.get("lgshrhdAfpubofrShrs")) + String(dma_comInfo.get("lssrpAfpubofrShrs")))); } },
        { childId: "__rb25", fn: function () { return String((String(dma_comInfo.get("lgshrhdAfpubofrShrRt")) + String(dma_comInfo.get("lssrpAfpubofrShrRt")))) + " %"; } },
        { childId: "__rb29", fn: function () { return String((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs")))); } },
        { childId: "__rb30", fn: function () { return String(dma_comInfo.get("ovr1pctShrRt")) + " %"; } },
        { childId: "__rb34", fn: function () { return String(dma_comInfo.get("ovr1pctAfpubofrShrRt")) + " %"; } },
        { childId: "__rb35", fn: function () { return String(dma_comInfo.get("ovr1pctRelprnCnt")) + " 명"; } },
        { childId: "__rb38", fn: function () { return String((String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs")))); } },
        { childId: "__rb39", fn: function () { return String(dma_comInfo.get("ovr1pctRelprnShrRt")) + " %"; } },
        { childId: "__rb43", fn: function () { return String(dma_comInfo.get("o1psrpAfpubofrShrRt")) + " %"; } },
        { childId: "__rb44", fn: function () { return String((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")))); } },
        { childId: "__rb45", fn: function () { return String((String(dma_comInfo.get("ovr1pctPrefstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs")))); } },
        { childId: "__rb46", fn: function () { return String(((String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs"))) + (String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "__rb47", fn: function () { return String((String(dma_comInfo.get("ovr1pctShrRt")) + String(dma_comInfo.get("ovr1pctRelprnShrRt")))) + " %"; } },
        { childId: "__rb48", fn: function () { return String((String(dma_comInfo.get("ovr1pctBfpubofrSaleShrs")) + String(dma_comInfo.get("o1psrpBfpubofrSaleShrs")))); } },
        { childId: "__rb49", fn: function () { return String((String(dma_comInfo.get("ovr1pctBfpubofrOferShrs")) + String(dma_comInfo.get("o1psrpBfpubofrOferShrs")))); } },
        { childId: "__rb50", fn: function () { return String((String(dma_comInfo.get("ovr1pctAfpubofrShrs")) + String(dma_comInfo.get("o1psrpAfpubofrShrs")))); } },
        { childId: "__rb51", fn: function () { return String((String(dma_comInfo.get("ovr1pctAfpubofrShrRt")) + String(dma_comInfo.get("o1psrpAfpubofrShrRt")))) + " %"; } },
        { childId: "__rb52", fn: function () { return String(dma_comInfo.get("minshrhdCnt")) + " 명"; } },
        { childId: "__rb55", fn: function () { return String((String(dma_comInfo.get("minshrhdCmstkShrs")) + String(dma_comInfo.get("minshrhdPrefstkShrs")))); } },
        { childId: "__rb56", fn: function () { return String(dma_comInfo.get("minshrhdShrRt")) + " %"; } },
        { childId: "__rb60", fn: function () { return String(dma_comInfo.get("minshrhdAfpubofrShrRt")) + " %"; } },
        { childId: "__rb61", fn: function () { return String(((String(dma_comInfo.get("minshrhdCmstkShrs")) + (String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")))) + (String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnCmstkShrs"))))); } },
        { childId: "__rb62", fn: function () { return String(((String(dma_comInfo.get("minshrhdPrefstkShrs")) + (String(dma_comInfo.get("lgshrhdPrefstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctPrefstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "__rb63", fn: function () { return String((((((String(dma_comInfo.get("minshrhdCmstkShrs")) + String(dma_comInfo.get("minshrhdPrefstkShrs"))) + (String(dma_comInfo.get("lgshrhdCmstkShrs")) + String(dma_comInfo.get("lgshrhdPrefstkShrs")))) + (String(dma_comInfo.get("lgshrhdRelprnCmstkShrs")) + String(dma_comInfo.get("lgshrhdRelprnPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctCmstkShrs")) + String(dma_comInfo.get("ovr1pctPrefstkShrs")))) + (String(dma_comInfo.get("ovr1pctRelprnCmstkShrs")) + String(dma_comInfo.get("ovr1pctRelprnPrefstkShrs"))))); } },
        { childId: "__rb64", fn: function () { return String(((((String(dma_comInfo.get("minshrhdShrRt")) + String(dma_comInfo.get("ovr1pctShrRt"))) + String(dma_comInfo.get("ovr1pctRelprnShrRt"))) + String(dma_comInfo.get("lgshrhdShrRt"))) + String(dma_comInfo.get("lgshrhdRelprnShrRt")))) + " %"; } },
        { childId: "__rb65", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdBfpubofrSaleShrs")) + String(dma_comInfo.get("lssrpBfpubofrSaleShrs"))) + String(dma_comInfo.get("ovr1pctBfpubofrSaleShrs"))) + String(dma_comInfo.get("o1psrpBfpubofrSaleShrs"))) + String(dma_comInfo.get("minshrhdBfpubofrSaleShrs")))); } },
        { childId: "__rb66", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdBfpubofrOferShrs")) + String(dma_comInfo.get("lssrpBfpubofrOferShrs"))) + String(dma_comInfo.get("ovr1pctBfpubofrOferShrs"))) + String(dma_comInfo.get("o1psrpBfpubofrOferShrs"))) + String(dma_comInfo.get("minshrhdBfpubofrOferShrs")))); } },
        { childId: "__rb67", fn: function () { return String((((String(dma_comInfo.get("minshrhdAfpubofrShrs")) + (String(dma_comInfo.get("lgshrhdAfpubofrShrs")) + String(dma_comInfo.get("lssrpAfpubofrShrs")))) + String(dma_comInfo.get("ovr1pctAfpubofrShrs"))) + String(dma_comInfo.get("o1psrpAfpubofrShrs")))); } },
        { childId: "__rb68", fn: function () { return String(((((String(dma_comInfo.get("lgshrhdAfpubofrShrRt")) + String(dma_comInfo.get("lssrpAfpubofrShrRt"))) + String(dma_comInfo.get("ovr1pctAfpubofrShrRt"))) + String(dma_comInfo.get("o1psrpAfpubofrShrRt"))) + String(dma_comInfo.get("minshrhdAfpubofrShrRt")))) + " %"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07330.btn_print_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_List
 * @description script dts List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_List = async function () {
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, COM_NM, STRT_DD, END_DD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, COM_NM, STRT_DD, END_DD", unresolved: "query_param:SCREN_ID,SCREN_PROCES_TP_CD,COM_NM,STRT_DD,END_DD" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/konex/ClmSchdl.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07330.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};
